#!/usr/bin/env python3
# Regenerates nis_scaler_embed.hpp from NIS_Scaler.h (NVIDIA Image Scaling, MIT).
# The shader is compiled at run time with D3DCompile, so its text is embedded.
# MSVC limits one string literal to ~16 KB, so the text is split into chunks.
import os
here = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(here, 'NIS_Scaler.h'), encoding='utf-8').read().replace('\r\n', '\n')
assert ')NIS"' not in src
chunks, cur = [], ''
for line in src.splitlines(keepends=True):
    if len(cur) + len(line) > 12000:
        chunks.append(cur); cur = ''
    cur += line
chunks.append(cur)
with open(os.path.join(here, 'nis_scaler_embed.hpp'), 'w', encoding='utf-8', newline='\n') as f:
    f.write('// GENERATED by make_embed.py from NIS_Scaler.h (NVIDIA Image Scaling v1.0.3,\n')
    f.write('// MIT licence, see licence.txt). Do not edit; re-run make_embed.py.\n#pragma once\n')
    f.write('namespace na::nis_embed {\ninline const char* const kScalerChunks[] = {\n')
    for c in chunks:
        f.write('R"NIS(' + c + ')NIS",\n')
    f.write('};\ninline constexpr unsigned kScalerChunkCount = %d;\n}\n' % len(chunks))
